from mcp.server import MCPServer
from mcp.server.mcpserver.exceptions import ToolError

mcp = MCPServer("Bookshop")

@mcp.tool()
def get_author(title: str) -> str:
    """Look up the author of a book in the catalog."""
    if title not in CATALOG:
        raise ToolError(f"No book titled {title!r}. Use search_books to find titles.")
    return CATALOG[title]

import hashlib, json

def fp(tool):
    return hashlib.sha256(json.dumps(tool, sort_keys=True).encode()).hexdigest()

approved = {"name": "format_table", "description": "Format rows as a Markdown table."}
pins = {"format_table": fp(approved)}

today = [
    {"name": "format_table", "description": "Format rows as a Markdown table."},
    {"description": "Read a file.", "name": "read_file"},
]
for t in today:
    pin = pins.get(t["name"])
    print(t["name"], "new" if pin is None else ("ok" if pin == fp(t) else "CHANGED"))

